nodes.info:
Feeds camgate (127.0.0.1:8788). Doors retained on terrarium/camera/doors every 1 s;
show-me retained on terrarium/camera/showme, auto-off 30 min, off on every NR start.
open stays null until each door has reported once (fail closed).

nodes.func:
// Camera Door Publisher -> terrarium/camera/doors (camgate privacy gate).
// Inputs: door_left / door_right (payload 1 = OPEN, 0 = closed), the serial
// heartbeat (no topic: only refreshes serial liveness) and a 1 s "tick".
// Fail closed:
//  - state is wiped in On Start, so nothing persisted by a previous Node-RED
//    process is ever trusted (no "memory" context store is configured);
//  - a door that has not reported in this process is null -> open null;
//  - no D22/D24 report for > 30 s (firmware re-reports every ~10 s) -> open
//    null, even while heartbeats keep serial_age_s fresh.
const DOOR_STALE_S = 30;
const now = Date.now() / 1000;
let left = context.get('left');
let right = context.get('right');
if (left === undefined) left = null;
if (right === undefined) right = null;

if (msg.topic === 'door_left' || msg.topic === 'door_right') {
    const p = msg.payload;   // strict: '' / null / junk must not read as closed
    const val = (p === 0 || p === '0') ? 0 : (p === 1 || p === '1') ? 1 : null;
    if (msg.topic === 'door_left') { left = val; context.set('left', val); }
    else { right = val; context.set('right', val); }
    context.set('last_serial_ts', now);
    context.set('door_ts', now);
} else if (msg.topic === 'tick') {
    // publish below
} else {
    // heartbeat: serial link is alive; do not publish (avoid flooding)
    context.set('last_serial_ts', now);
    return null;
}

const fresh = (t) => typeof t === 'number' && isFinite(t);
const last = context.get('last_serial_ts');
const age = fresh(last) ? Math.max(0, now - last) : 1e9;
const doorTs = context.get('door_ts');
const doorsFresh = fresh(doorTs) && (now - doorTs) <= DOOR_STALE_S;
const open = (!doorsFresh || left === null || right === null) ? null : !!(left || right);
return {
    topic: 'terrarium/camera/doors',
    payload: { open: open, left: left, right: right, serial_age_s: age, ts: now }
};

nodes.initialize:
// Fail closed across restarts: forget any door state persisted by a previous
// process (localfilesystem is the only context store). Setting undefined
// deletes the key. Input messages are queued until this has run.
for (const k of ['left', 'right', 'last_serial_ts', 'door_ts']) {
    context.set(k, undefined);
}

nodes.func:
// Show-me timer -> terrarium/camera/showme. Auto-off after 1800 s.
// Outputs: [0] MQTT showme, [1] switch reset (switch passthru is off, so this
// never re-emits), [2] countdown text.
// The 1800 s timer is a deadline ("until", in node context) checked by the
// 1 s tick, so no setTimeout handle has to survive deploys or restarts.
// On every Node-RED start the "startup" inject publishes off, so a retained
// "on" cannot outlive a restart.
const MAX_S = 1800;
const now = Date.now() / 1000;

function off() {
    context.set('until', null);
    context.set('shown_min', null);
    return [
        { topic: 'terrarium/camera/showme', payload: { on: false, until: null, ts: now } },
        { payload: false },
        { payload: 'off' }
    ];
}

if (msg.topic === 'startup') return off();

if (msg.topic === 'tick') {
    const until = context.get('until');
    if (typeof until !== 'number') return null;          // inactive
    if (now >= until) return off();                        // expired
    const mins = Math.ceil((until - now) / 60);
    if (mins === context.get('shown_min')) return null;   // no UI change
    context.set('shown_min', mins);
    return [null, null, { payload: mins + ' min left' }];
}

// From the "Camera show-me" switch.
if (msg.payload === true) {
    const until = now + MAX_S;
    context.set('until', until);
    context.set('shown_min', MAX_S / 60);
    return [
        { topic: 'terrarium/camera/showme', payload: { on: true, until: until, ts: now } },
        null,
        { payload: (MAX_S / 60) + ' min left' }
    ];
}
return off();
